// ***************
// Filename: watchdog_top.sv
// Author: FPGA Cores 4 U
// Description: watchdog with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map watchdog_regs
//   (u_regs, src/include/watchdog_regs.sv, ID "WDOG", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic watchdog (u_core,
//   src/watchdog.sv), joined by their register ports (cfg_* to the logic,
//   sts_* back). Generated by ip/scripts/regmap_gen.py from
//   watchdog_regs.json and the ports of watchdog: regenerate after changing
//   either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-12
module watchdog_top #(
  parameter int RESET_CYCLES = 16
) (
  input  logic        aclk,
  input  logic        aresetn,
  input  logic [7:0]  s_axil_awaddr,
  input  logic        s_axil_awvalid,
  output logic        s_axil_awready,
  input  logic [31:0] s_axil_wdata,
  input  logic [3:0]  s_axil_wstrb,
  input  logic        s_axil_wvalid,
  output logic        s_axil_wready,
  output logic [1:0]  s_axil_bresp,
  output logic        s_axil_bvalid,
  input  logic        s_axil_bready,
  input  logic [7:0]  s_axil_araddr,
  input  logic        s_axil_arvalid,
  output logic        s_axil_arready,
  output logic [31:0] s_axil_rdata,
  output logic [1:0]  s_axil_rresp,
  output logic        s_axil_rvalid,
  input  logic        s_axil_rready,
  output logic        irq_o,
  output logic        wdt_reset_o
);
  // register ports between the register map and the logic
  logic [2:0] cfg_ctrl;
  logic cfg_ctrl_wr;
  logic [2:0] sts_ctrl;
  logic [31:0] cfg_timeout;
  logic [31:0] cfg_prescale;
  logic [31:0] cfg_pretimeout;
  logic [31:0] cfg_window_open;
  logic [31:0] cfg_kick;
  logic cfg_kick_wr;
  logic [3:0] cfg_status;
  logic cfg_status_wr;
  logic [3:0] sts_status;
  logic [31:0] sts_count;

  watchdog_regs u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .ctrl_o(cfg_ctrl),
    .ctrl_wr_o(cfg_ctrl_wr),
    .ctrl_i(sts_ctrl),
    .timeout_o(cfg_timeout),
    .timeout_wr_o(),
    .prescale_o(cfg_prescale),
    .prescale_wr_o(),
    .pretimeout_o(cfg_pretimeout),
    .pretimeout_wr_o(),
    .window_open_o(cfg_window_open),
    .window_open_wr_o(),
    .kick_o(cfg_kick),
    .kick_wr_o(cfg_kick_wr),
    .status_o(cfg_status),
    .status_wr_o(cfg_status_wr),
    .status_i(sts_status),
    .count_i(sts_count)
  );
  watchdog #(
    .RESET_CYCLES(RESET_CYCLES)
  ) u_core (
    .aclk,
    .aresetn,
    .irq_o,
    .wdt_reset_o,
    .cfg_ctrl,
    .cfg_ctrl_wr,
    .sts_ctrl,
    .cfg_timeout,
    .cfg_prescale,
    .cfg_pretimeout,
    .cfg_window_open,
    .cfg_kick,
    .cfg_kick_wr,
    .cfg_status,
    .cfg_status_wr,
    .sts_status,
    .sts_count
  );
endmodule
